  ?z a brick:Zone ; rdfs:label "Perimeter_bot_ZN_2" .
  ?p brick:hasProperty ?point .
  ?point ref:hasTimeseriesId ?ts .
  ?point a brick:Occupancy .
}

SELECT ?z ?label ?ts ?p WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?label }
  OPTIONAL { ?p brick:isPointOf ?z . ?point ref:hasTimeseriesId ?ts }
  FILTER(str(?z) != "none" || true)
  FILTER(CONTAINS(str(?z), "erimeter") || CONTAINS(str(?label), "erimeter"))
}

